// Determine run mode based on trigger source
// Scheduled 6h trigger → incremental
// Scheduled 15m trigger → backfill
// Manual trigger → check backfill status first, then incremental

const triggerNode = $execution.customData?.get('triggerNode') || '';
const manualMode = $input.first()?.json?.mode || 'auto';

let mode = 'incremental';

// If coming from the backfill scheduler
if ($execution.customData?.get('source') === 'backfill' || triggerNode.includes('Backfill')) {
  mode = 'backfill';
}

// Manual override
if (manualMode === 'backfill') mode = 'backfill';
if (manualMode === 'backfill-init') mode = 'backfill-init';
if (manualMode === 'backfill-status') mode = 'backfill-status';
if (manualMode === 'status') mode = 'status';

return [{ json: { mode, timestamp: new Date().toISOString() } }];

// Parse the engine output and extract the result JSON
const stdout = $input.first()?.json?.stdout || '';
const stderr = $input.first()?.json?.stderr || '';
const exitCode = $input.first()?.json?.exitCode;

// Extract the structured result
let result = null;
const resultMarker = '__ENGINE_RESULT__';
const markerIndex = stdout.indexOf(resultMarker);

if (markerIndex !== -1) {
  const jsonStr = stdout.substring(markerIndex + resultMarker.length).trim();
  try {
    result = JSON.parse(jsonStr);
  } catch (e) {
    console.error('Failed to parse engine result:', e.message);
  }
}

// Extract log lines (everything before the result marker)
const logs = markerIndex !== -1 
  ? stdout.substring(0, markerIndex).trim()
  : stdout.trim();

const success = exitCode === 0;

return [{
  json: {
    success,
    exitCode,
    result,
    logLines: logs.split('\n').length,
    lastLogs: logs.split('\n').slice(-20).join('\n'),
    stderr: stderr ? stderr.substring(0, 1000) : '',
    executedAt: new Date().toISOString()
  }
}];

// Log success metrics
const data = $input.first()?.json;
console.log('Engine run completed successfully');
console.log('Result:', JSON.stringify(data.result, null, 2));
return [$input.first()];

// Log failure details for debugging
const data = $input.first()?.json;
console.error('Engine run FAILED');
console.error('Exit code:', data.exitCode);
console.error('Last logs:', data.lastLogs);
console.error('Stderr:', data.stderr);

// Could add notification here (email, Slack, etc.)

return [$input.first()];
